-- Perfect City block groups (GENERATED by tools/perfect-city/export_perfect_city.py units-seed from assets/perfect-city/*.census.js).
-- US Census Bureau, 2020 Census P1 population and block-group centres (public domain). Safe in the repo; the OpenStreetMap places are NOT here.
-- Runs AFTER migration 20261127000900_perfect_city_places.sql (it fills that migration's table). Undo: the 000900 rollback
-- (supabase/rollbacks/20261127000900_perfect_city_places_rollback.sql), or simply run this file again: it starts by deleting every row.
-- The last statement prints PASS when the row and people counts are the expected ones, else STOP (RENDERER 10:17).
begin;
delete from ryagram_private.perfect_city_units;
commit;
select case when count(*) = 546 and sum(pop) = 705275 then 'PASS: 546 block groups, 705275 people' else 'STOP: expected 546 block groups and 705275 people, got ' || count(*) || ' and ' || coalesce(sum(pop), 0) end as seed_check from ryagram_private.perfect_city_units;
